import { LitElement, html, nothing, unsafeCSS } from 'lit';

import { icon } from '../../icons/icon';
import '../ListItem/ds-list-item';
import css from './DropdownMenu.css?inline';

export class DsDropdownMenu extends LitElement {
  static override styles = [unsafeCSS(':host { display: contents; }'), unsafeCSS(css)];
  static override properties = {
    state: { type: String, reflect: true, attribute: "state" },
    active: { state: true },
    showSearch: { type: Boolean, attribute: "show-search" },
    grouped: { type: Boolean, attribute: "grouped" },
    forceState: { type: String, attribute: 'data-force-state' },
  };

  /** Figma: State */
  declare state: "default" | "loading" | "empty";
  /** The active item (aria-activedescendant); -1 for none. */
  declare active: number;
  /** Figma: Show Search */
  declare showSearch: boolean;
  /** Figma: Grouped */
  declare grouped: boolean;
  /** Renders a pseudo state statically for docs and visual tests: "hover", "pressed" or "focus". */
  declare forceState: string | undefined;

  constructor() {
    super();
    this.state = "default";
    this.active = -1;
    this.showSearch = false;
    this.grouped = false;
    this.addEventListener('keydown', this.moveActive);
  }

  private items() {
    return [...this.renderRoot.querySelectorAll<HTMLElement>('[data-ds-item]')];
  }

  /** Arrow keys, Home and End move the active item; Enter and Space choose it (WAI-ARIA menu). */
  private moveActive = (event: KeyboardEvent) => {
    if (!(!["loading","empty"].includes(String(this.state)))) return;
    const items = this.items();
    if (!items.length) return;
    const at = items.findIndex((x) => Number(x.dataset.dsIndex) === this.active);
    const step = ({ ArrowDown: 1, ArrowUp: -1 } as Record<string, number>)[event.key];
    const to = step !== undefined ? (at < 0 ? (step > 0 ? 0 : items.length - 1) : (at + step + items.length) % items.length) : event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : -1;
    if (to >= 0) {
      event.preventDefault();
      this.active = Number(items[to]!.dataset.dsIndex);
      items[to]!.scrollIntoView?.({ block: 'nearest' });
    } else if ((event.key === ' ' || event.key === 'Enter') && at >= 0) {
      event.preventDefault();
      items[at]!.click();
    }
  };

  /** Sets what DropdownMenu drives on slotted children (the ones the page provides instead of the Figma examples). */
  private applyRepeated = () => {
    const slots = [...(this.renderRoot.querySelectorAll('slot') ?? [])] as HTMLSlotElement[];
    {
      const slot = slots.find((s) => s.name === "");
      const items = (slot?.assignedElements() ?? []).filter((el) => el.localName === "ds-list-item");
      items.forEach((el, i) => {
        const item = el as unknown as Record<string, unknown>;

        void i;
      });
    }
  };

  override updated() {
    this.applyRepeated();
  }

  override render() {
    return html`<div class="root" part="root" data-state=${this.state} role=${!["loading","empty"].includes(String(this.state)) ? "menu" : nothing} tabindex=${!["loading","empty"].includes(String(this.state)) ? '0' : nothing} aria-activedescendant=${!["loading","empty"].includes(String(this.state)) && this.active >= 0 ? `item-${this.active}` : nothing} aria-labelledby=${!["loading","empty"].includes(String(this.state)) ? 'group-label' : nothing} aria-busy=${this.state === "loading" ? 'true' : nothing} data-force-state=${this.forceState ?? nothing}>
        ${this.showSearch ? html`<div class="searchRow">
          <span class="searchIcon" aria-hidden="true">${icon("actionSearch16")}</span>
          <span class="searchPlaceholder">${"Search…"}</span>
        </div>` : nothing}
        ${this.grouped ? html`<div class="groupLabelWrap">
          <span id="group-label" class="groupLabel">${"Group label"}</span>
        </div>` : nothing}
        <div class="optionsList">
          <slot @slotchange=${this.applyRepeated}>
            <span class="option"><ds-list-item style="display: block" role="menuitem" id="item-0" data-ds-item data-ds-index="0" data-force-state=${this.active === 0 ? 'focus' : nothing} .state=${"selected"} .hasTrailingControl=${true}></ds-list-item></span>
                      <span class="option"><ds-list-item style="display: block" role="menuitem" id="item-1" data-ds-item data-ds-index="1" data-force-state=${this.active === 1 ? 'focus' : nothing}></ds-list-item></span>
                      <span class="option"><ds-list-item style="display: block" role="menuitem" id="item-2" data-ds-item data-ds-index="2" data-force-state=${this.active === 2 ? 'focus' : nothing}></ds-list-item></span>
                      <span class="option"><ds-list-item style="display: block" role="menuitem" id="item-3" data-ds-item data-ds-index="3" data-force-state=${this.active === 3 ? 'focus' : nothing} .disabled=${true}></ds-list-item></span>
          </slot>
        </div>
        <div class="loadingRow">
          <span class="loadingIcon" aria-hidden="true">${icon("statusLoading16")}</span>
          <span class="loadingText">${"Loading options…"}</span>
        </div>
        <div class="emptyRow">
          <span class="emptyText">${"No results found"}</span>
        </div>
      </div>`;
  }
}

if (!customElements.get('ds-dropdown-menu')) customElements.define('ds-dropdown-menu', DsDropdownMenu);

declare global {
  interface HTMLElementTagNameMap {
    'ds-dropdown-menu': DsDropdownMenu;
  }
}
